"""Reorganize existing laptop results under the user-provided Stack Bowls SOP.

Read-only numerical aggregation: no simulator import, no native rollout.
"""
import argparse,hashlib,json
from pathlib import Path


def summarize(root):
    root=Path(root);raw=json.loads((root/'full-metrics.json').read_text());attempt=json.loads((root/'reference-final-attempt.json').read_text());engines={'MuJoCo Warp':'mujoco_warp_it1','SAP Warp':'sap_it1'};consistency={};inputs={};outcomes={}
    for label,name in engines.items():
        a=raw['results'][name];g=a['geometry'];pairs={p:{'sampled_peak_lower_bound_mm':v['lower_bound_m']*1000,'sampled_peak_upper_bound_mm':v['depth_m']*1000,'upper_peak_time_s':v['time_s'],'lower_peak_time_s':v['lower_bound_time_s']} for p,v in g['pairs'].items()}
        contacts={p:{'window_s':v['window_s'],'samples':v['samples'],'candidate_duty':v['candidate_duty'],'force_threshold_N':.01,**v['thresholds']['0.01'],'threshold_sensitivity':v['thresholds']} for p,v in a['contact'].items()}
        consistency[label]={'geometric_validity':{'method':g['method'],'sample_dt_s':g['dt_s'],'sample_count':g['samples'],'run_window_s':[0,14.46],'pairs':pairs,'global_component_peak_bounds_mm':[max(v['sampled_peak_lower_bound_mm'] for v in pairs.values()),max(v['sampled_peak_upper_bound_mm'] for v in pairs.values())],'local_wall_thickness_audit':None,'wall_crossing_audit':None,'note':'Bounds concern the sampled maximum over convex component pairs, not exact union penetration or a continuous-time maximum. Wide finger-contact bounds prevent a global geometry ranking.'},'contact_continuity':contacts,'post_release_settling':{'primary':a['settling']['source_final_s'],'supplementary_appended_tail':a['settling']['tail_final_s'],'path_length_mm':None,'tilt_fluctuation_deg':None,'note':'Primary window is inside recorded source time. Tail motion is supplementary, not reference pose evidence.'}}
        inputs[label]={'drive_gate_pass':a['health']['drive_gate_pass'],'tracking':a['health']['tracking'],'finite':a['health']['finite'],'steps':a['health']['steps'],'expected_steps':a['health']['expected_steps'],'truncated':a['health']['truncated'],'use':'input implementation checks; not object-trajectory fidelity metrics or automatic task-failure labels'}
        outcomes[label]={'reference_observed_success':True,'simulation_observed_insertion':True,'complete_release_observed':True,'post_release_peak_gripper_normal_force_N':a['release_check']['peak_laptop_gripper_normal_force_N'],'observed_outcome_agreement':True,'valid_success':None,'valid_outcome_agreement':None,'false_success':None,'false_success_status':'not applicable under observed-success reference label','false_failure':None,'reason':'Local thickness and wall-crossing validity audits are incomplete; do not turn missing validity into success or failure.'}
    result={'mode':'existing-only; no new simulation','standard':'user-provided Stack Bowls evaluation SOP, adapted to one rectangular laptop','physical_fidelity':{'object_trajectory_error':{'position_rmse_m':None,'orientation_error_deg':None,'accepted_object_frames':0,'total_source_object_frames':325,'uncertainty':None,'status':'not evaluated: no admitted object reference trajectory'},'final_pose_error':{'position_error_m':None,'orientation_error_deg':None,'accepted_objects':0,'total_objects':1,'accepted_source_window_object_frames':0,'source_window_object_frames':12,'reference_attempt':attempt,'uncertainty':None,'status':'reference fit rejected; residual is not simulation error'},'note':'Zero accepted coverage does not mean the images are invisible. Initial reconstruction, gripper tracking and engine-to-engine differences are not reference trajectory errors.'},'simulation_consistency':consistency,'task_outcome':outcomes,'input_checks':inputs,'source_time_offset_s':9.,'primary_settling_window_run_s':[12.5,12.96],'primary_settling_window_source_s':[21.5,21.96],'r_per_configuration':1,'episode_count':1,'overall_fidelity_ranking':None,'inputs_sha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in ['full-metrics.json','full-stages.json','reference-final-attempt.json']}}
    (root/'full-sop-summary.json').write_text(json.dumps(result,indent=2,ensure_ascii=False));print(json.dumps({'mode':result['mode'],'primary_window':result['primary_settling_window_source_s'],'engines':list(consistency)},ensure_ascii=False))

if __name__=='__main__':
    a=argparse.ArgumentParser();a.add_argument('root');summarize(a.parse_args().root)
